      if (primary != null || FAILURES.get() != 0 || LEAKS.get() != 0) {
        throw closedFault(primary != null ? FaultCode.ORIGINAL_FAILURE
            : LEAKS.get() != 0 ? FaultCode.LEAK : FaultCode.INCOMPLETE,
            observation.ordinal, LEAKS.get(), FAILURES.get());
      }
    } catch (Throwable original) {
      if (observation != null && original != primary) {
        throwable(original);
      }
      // Even accessor, graph, cleanup and scanner failures cross only this closed boundary.
      throw closedFault(primary != null ? FaultCode.ORIGINAL_FAILURE : FaultCode.INCOMPLETE,
          observation == null ? 0 : observation.ordinal, LEAKS.get(), FAILURES.get() + 1);
    } finally {
      CURRENT.set(null);
      if (SERIAL.isHeldByCurrentThread()) {
        SERIAL.unlock();
      }
    }
  }

  static AssertionError safeLifecycleFailure(Throwable original) {
    try {
      throwable(original);
      scanAll();
    } catch (Throwable ignored) {
      fail();
    }
    return closedFault(FaultCode.ORIGINAL_FAILURE, 0, LEAKS.get(), FAILURES.get() + 1);
  }

  static void finishClass(Throwable primary, boolean resourcesClosed) {
    boolean restored = false;
    try {
      throwable(primary);
      for (FaultCase observation : CASES) {
        try { observation.drain(); }
        catch (Throwable cleanup) { throwable(cleanup); fail(); }
        throwable(observation.original);
        for (Scenario scenario : observation.scenarios) {
          throwable(scenario.failure.get());
          throwable(scenario.peerFailure.get());
        }
        for (SourceStopOwner owner : observation.owners) {
          throwable(owner.failure.get());
          throwable(owner.guardFailure.get());
        }
      }
      try { LIFECYCLE.drain(); }
      catch (Throwable cleanup) { throwable(cleanup); fail(); }
      if (!resourcesClosed) {
        fail();
      }
      if (logging != null) {
        try { logging.verifyRoutes(true); }
        catch (Throwable unavailable) { throwable(unavailable); fail(); }
        try { logging.inspectStatus(); }
        catch (Throwable unavailable) { throwable(unavailable); fail(); }
      }
      scanAll();
      // Unreaped owners/resources retain quarantine, never restore output underneath them.
      if (resourcesClosed && CASES.stream().allMatch(FaultCase::resourcesComplete)
          && LIFECYCLE.resourcesComplete() && logging != null) {
        logging.restore();
        restored = true;
        logging.inspectStatus();
        scanAll(); // Includes real footer/header/restoration emissions and late status errors.
      }
    } catch (Throwable original) {
      throwable(original);
      fail();
    } finally {
      if (restored) {
        for (SinkBytes sink : SINKS) {
          Arrays.fill(sink.bytes, (byte) 0);
        }
        SINKS.clear();
        logging.wipe();
        for (FaultCase observation : CASES) {
          observation.dispose();
        }
        LIFECYCLE.dispose();
        BY_TEST.clear();
        BY_SESSION.clear();
        STOP_OWNERS.clear();
        CASES.clear();
      }
    }
    if (primary != null || !restored || FAILURES.get() != 0 || LEAKS.get() != 0) {
      throw closedFault(primary != null ? FaultCode.ORIGINAL_FAILURE : FaultCode.RESTORATION,
          0, LEAKS.get(), FAILURES.get() + 1);
    }
  }

  static void fail() { FAILURES.incrementAndGet(); }

  static boolean reserve(int bytes) {
    if (bytes < 0 || bytes > AGGREGATE_LIMIT) { fail(); return false; }
    while (true) {
      int current = BYTES.get();
      if (current > AGGREGATE_LIMIT - bytes) { fail(); return false; }
      if (BYTES.compareAndSet(current, current + bytes)) { return true; }
    }
  }

  static FaultCase responseCase() {
    var peer = PEER_CASE.get();
    return peer == null ? currentCase() : peer;
  }

  static void observe(String label, Object existing) {
    // Only already-returned typed values; never invokes an arbitrary object's toString.
    try {
      typed(label, existing, 0);
    } catch (Throwable ignored) {
      fail();
    }
  }

  private static void typed(String label, Object value, int depth) {
    if (depth > 32) { fail(); return; }
    if (value == null) { return; }
    if (value instanceof String text) {
      if (text.length() > FIELD_LIMIT / 4) { fail(); return; }
      byte[] bytes = text.getBytes(StandardCharsets.UTF_8);
      try { capture(label, bytes, false); }
      finally { Arrays.fill(bytes, (byte) 0); }
    } else if (value instanceof byte[] bytes) {
      capture(label, bytes, false);
    } else if (value instanceof char[] chars) {
      if (chars.length > FIELD_LIMIT / 4) { fail(); return; }
      typed(label, new String(chars), depth + 1);
    } else if (value instanceof JsonNode node) {
      if (node.isObject()) {
        node.fields().forEachRemaining(field -> {
          typed(label, field.getKey(), depth + 1);
          typed(label, field.getValue(), depth + 1);
        });
      } else if (node.isArray()) {
        node.forEach(child -> typed(label, child, depth + 1));
      } else if (node.isTextual()) {
        typed(label, node.textValue(), depth + 1);
      } else if (!node.isNull() && !node.isNumber() && !node.isBoolean()) {
        fail();
      }
    } else if (value instanceof Map<?, ?> map) {
      map.forEach((key, item) -> {
        typed(label, key, depth + 1);
        typed(label, item, depth + 1);
      });
    } else if (value instanceof java.util.Collection<?> values) {
      values.forEach(item -> typed(label, item, depth + 1));
    } else if (value instanceof Number number) {
      if (Set.of(Byte.class, Short.class, Integer.class, Long.class, Float.class, Double.class,
          java.math.BigInteger.class, java.math.BigDecimal.class).contains(number.getClass())) {
        typed(label, number.toString(), depth + 1); // Only the exact known JDK value types.
      } else { fail(); }
    } else if (value instanceof Boolean || value instanceof UUID || value instanceof Instant) {
      typed(label, value.toString(), depth + 1); // These exact value types are final.
    } else if (value instanceof Enum<?> code) {
      typed(label, code.name(), depth + 1);
    } else if (value instanceof Throwable original) {
      throwable(original);
    } else {
      fail(); // Opaque is UNOBSERVED, never a zero-hit target.
    }
  }

  static void capture(String label, byte[] actual, boolean source) {
    if (actual == null) { fail(); return; }
    if (actual.length > FIELD_LIMIT || !reserve(actual.length)) {
      fail();
      return;
    }
    SINKS.add(new SinkBytes(label, actual.clone(), source));
  }

  static void throwable(Throwable original) {
    if (original == null) { return; }
    try {
      var seen = java.util.Collections.newSetFromMap(new java.util.IdentityHashMap<Throwable, Boolean>());
      var queue = new java.util.ArrayDeque<Throwable>();
      queue.add(original);
      int frames = 0;
      while (!queue.isEmpty()) {
        Throwable next = queue.removeFirst();
        if (!seen.add(next)) { continue; }
        if (seen.size() > 64) { fail(); return; }
        typed("ORIGINAL_THROWABLE", next.getMessage(), 0);
        for (StackTraceElement frame : next.getStackTrace()) {
          if (++frames > 4096) { fail(); return; }
          // Exact JDK StackTraceElement representation, not arbitrary Throwable.toString.
          typed("ORIGINAL_THROWABLE_STACK", frame.toString(), 0);
        }
        if (next.getCause() != null) { queue.add(next.getCause()); }
        queue.addAll(Arrays.asList(next.getSuppressed()));
        if (next instanceof java.sql.SQLException sql && sql.getNextException() != null) {
          queue.add(sql.getNextException());
        }
      }
    } catch (Throwable ignored) {
      fail();
    }
  }

  static void raw(ch.qos.logback.classic.spi.ILoggingEvent event) {
    try {
      if (EVENTS.incrementAndGet() > EVENT_LIMIT) { fail(); return; }
      RAW_FIELDS.incrementAndGet();
      if (!"FAULT_CAPTURE_ROUTE_REGISTERED".equals(event.getMessage())) { PRODUCT_EVENTS.incrementAndGet(); }
      typed("RAW_LOG_MESSAGE", event.getMessage(), 0);
      typed("RAW_LOG_FORMATTED", event.getFormattedMessage(), 0);
      typed("RAW_LOG_MDC", event.getMDCPropertyMap(), 0);
      Object[] arguments = event.getArgumentArray();
      if (arguments != null) {
        if (arguments.length > 64) { fail(); return; }
        for (Object argument : arguments) { typed("RAW_LOG_ARGUMENT", argument, 0); }
      }
      var markers = event.getMarkerList();
      if (markers != null) {
        var seen = java.util.Collections.newSetFromMap(new java.util.IdentityHashMap<org.slf4j.Marker, Boolean>());
        var queue = new java.util.ArrayDeque<>(markers);
        while (!queue.isEmpty()) {
          var marker = queue.removeFirst();
          if (!seen.add(marker)) { continue; }
          if (seen.size() > 64) { fail(); break; }
          typed("RAW_LOG_MARKER", marker.getName(), 0);
          marker.iterator().forEachRemaining(queue::addLast);
        }
      }
      var keyValues = event.getKeyValuePairs();
      if (keyValues != null) {
        if (keyValues.size() > 64) { fail(); return; }
        for (var pair : keyValues) {
          typed("RAW_LOG_KEY", pair.key, 0);
          typed("RAW_LOG_VALUE", pair.value, 0);
        }
      }
      for (StackTraceElement frame : event.getCallerData()) {
        typed("RAW_LOG_CALLER", frame.toString(), 0);
      }
      proxy(event.getThrowableProxy());
    } catch (Throwable ignored) {
      fail(); // Logback must not swallow/log a content-bearing observer exception.
    }
  }

  private static void proxy(ch.qos.logback.classic.spi.IThrowableProxy original) {
    if (original == null) { return; }
    var seen = java.util.Collections.newSetFromMap(
        new java.util.IdentityHashMap<ch.qos.logback.classic.spi.IThrowableProxy, Boolean>());
    var queue = new java.util.ArrayDeque<ch.qos.logback.classic.spi.IThrowableProxy>();
    queue.add(original);
    int frames = 0;
    while (!queue.isEmpty()) {
      var next = queue.removeFirst();
      if (!seen.add(next)) { continue; }
      if (seen.size() > 64) { fail(); return; }
      typed("RAW_LOG_THROWABLE", next.getMessage(), 0);
      for (var frame : next.getStackTraceElementProxyArray()) {
        if (++frames > 4096) { fail(); return; }
        typed("RAW_LOG_STACK", frame.getStackTraceElement().toString(), 0);
      }
      if (next.getCause() != null) { queue.add(next.getCause()); }
      if (next.getSuppressed() != null) { queue.addAll(Arrays.asList(next.getSuppressed())); }
    }
  }

  static void scanAll() {
    for (FaultCase observation : CASES) {
      for (char[] release : observation.releases) {
        final int variantReservation = 512 * 1024;
        if (!reserve(variantReservation)) { continue; }
        List<byte[]> variants = FaultScanner.variants(release);
        try {
          for (SinkBytes sink : SINKS) {
            if (!sink.source && FaultScanner.containsAny(sink.bytes, variants)) {
              LEAKS.incrementAndGet();
            }
          }
          if (logging != null) {
            for (ConsoleRoute route : logging.consoles.values()) {
              int copyBytes = route.quarantine.bytes.length;
              if (!reserve(copyBytes)) { continue; }
              byte[] encoded = route.quarantine.copy();
              try {
                if (FaultScanner.containsAny(encoded, variants)) { LEAKS.incrementAndGet(); }
              } finally { Arrays.fill(encoded, (byte) 0); BYTES.addAndGet(-copyBytes); }
            }
          }
        } finally {
          for (byte[] variant : variants) { Arrays.fill(variant, (byte) 0); }
          BYTES.addAndGet(-variantReservation);
        }
      }
    }
  }
}

private record SinkBytes(String label, byte[] bytes, boolean source) {}

private static final class FaultCase {
  final int ordinal;
  final List<Scenario> scenarios = new java.util.concurrent.CopyOnWriteArrayList<>();
  final List<SourceStopOwner> owners = new java.util.concurrent.CopyOnWriteArrayList<>();
  final List<char[]> releases = new java.util.concurrent.CopyOnWriteArrayList<>();
  final Set<Thread> callers = ConcurrentHashMap.newKeySet(), peers = ConcurrentHashMap.newKeySet();
  final AtomicInteger activePeers = new AtomicInteger(), peerEntries = new AtomicInteger(), peerExits = new AtomicInteger();
  final AtomicInteger responseAttempts = new AtomicInteger(), responseWrites = new AtomicInteger();
  final AtomicInteger sourceAttempts = new AtomicInteger(), sourcePositive = new AtomicInteger();
  volatile Throwable original;
  final int productEventsBefore = FaultCapture.PRODUCT_EVENTS.get();

  FaultCase(int ordinal) { this.ordinal = ordinal; }
  boolean hasRelease() { return !releases.isEmpty(); }

  void release(char[] actual, Thread caller) {
    FaultCapture.logging.verifyRoutes(false);
    if (actual.length == 0 || actual.length > 4096 || FaultCapture.FAILURES.get() != 0) {
      FaultCapture.fail();
      throw closedFault(FaultCode.PREREQUISITE, ordinal, 0, FaultCapture.FAILURES.get());
    }
    if (!FaultCapture.reserve(actual.length * 2)) {
      FaultCapture.fail();
      throw closedFault(FaultCode.INCOMPLETE, ordinal, 0, FaultCapture.FAILURES.get());
    }
    releases.add(actual.clone());
    callers.add(caller);
  }

  void requireReleased(String actualReceived) {
    char[] received = actualReceived.toCharArray();
    try {
      if (releases.size() != 1 || !Arrays.equals(releases.getFirst(), received)) {
        FaultCapture.fail();
        throw closedFault(FaultCode.INCOMPLETE, ordinal, 0, FaultCapture.FAILURES.get());
      }
    } finally { Arrays.fill(received, '\0'); }
  }

  void responseAttempt(byte[] actualBytes, boolean source) {
    responseAttempts.incrementAndGet();
    FaultCapture.capture(source ? "CONTROLLED_503_SOURCE" : "RELAY_RESPONSE_BYTES", actualBytes, source);
    if (source) {
      sourceAttempts.incrementAndGet();
      if (releases.size() == 1) {
        final int variantReservation = 512 * 1024;
        if (!FaultCapture.reserve(variantReservation)) { return; }
        var variants = FaultScanner.variants(releases.getFirst());
        try {
          if (FaultScanner.containsAny(actualBytes, variants)) { sourcePositive.incrementAndGet(); }
          else { FaultCapture.fail(); }
        } finally {
          variants.forEach(bytes -> Arrays.fill(bytes, (byte) 0));
          FaultCapture.BYTES.addAndGet(-variantReservation);
        }
      } else { FaultCapture.fail(); }
    }
  }

  void drain() {
    // Actual operation/peer exit is the barrier; counter zero alone never grants completion.
    for (Thread caller : callers) {
      if (caller != Thread.currentThread()) { joinUninterruptibly(caller); }
    }
    for (SourceStopOwner owner : owners) {
      try { owner.drainUninterruptibly(); }
      catch (Throwable cleanup) { FaultCapture.throwable(cleanup); FaultCapture.fail(); }
    }
    for (Thread peer : peers) {
      if (peer != Thread.currentThread()) { joinUninterruptibly(peer); }
    }
    if (!resourcesComplete()) { FaultCapture.fail(); }
    for (Scenario scenario : scenarios) {
      if (scenario.problemSource && hasRelease()
          && (sourceAttempts.get() != 1 || sourcePositive.get() != 1)) {
        FaultCapture.fail();
      }
    }
  }

  boolean resourcesComplete() {

  boolean resourcesComplete() {
    return callers.stream().noneMatch(thread -> thread != Thread.currentThread() && thread.isAlive())
        && peers.stream().noneMatch(thread -> thread != Thread.currentThread() && thread.isAlive())
        && activePeers.get() == 0 && peerExits.get() == peerEntries.get()
        && owners.stream().allMatch(SourceStopOwner::operationsComplete);
  }

  void countOnlyReport() {
    System.out.println("{\"faultSinkOrdinal\":" + ordinal
        + ",\"actualReleases\":" + releases.size() + ",\"responseAttempts\":" + responseAttempts.get()
        + ",\"responseWrites\":" + responseWrites.get() + ",\"controlledSourcePositive\":" + sourcePositive.get()
        + ",\"rawEventsCumulative\":" + FaultCapture.EVENTS.get()
        + ",\"actualNonMarkerRawEvents\":" + (FaultCapture.PRODUCT_EVENTS.get() - productEventsBefore)
        + ",\"rawFieldsCumulative\":" + FaultCapture.RAW_FIELDS.get()
        + ",\"reservedObservationBytes\":" + FaultCapture.BYTES.get()
        + ",\"leaks\":" + FaultCapture.LEAKS.get() + ",\"observationFailures\":" + FaultCapture.FAILURES.get() + "}");
  }

  void dispose() {
    releases.forEach(chars -> Arrays.fill(chars, '\0'));
    releases.clear();
    for (Scenario scenario : scenarios) {
      scenario.failure.set(null);
      scenario.peerFailure.set(null);
      scenario.request.set(null);
      scenario.chars.set(null);
      scenario.source = null;
      scenario.configuration = null;
      scenario.sessionId = null;
    }
    scenarios.clear();
    owners.clear();
    callers.clear();
    peers.clear();
    original = null;
  }
}

/** The original encoder writes here once; close is intentionally a no-op for public stream swap. */
private static final class QuarantineBytes extends java.io.OutputStream {
  private byte[] bytes;
  QuarantineBytes() {
    int allocation = 4 * 1024 * 1024;
    if (!FaultCapture.reserve(allocation)) {
      FaultCapture.fail();
      bytes = new byte[0];
    } else { bytes = new byte[allocation]; }
  }
  private int size;
  @Override public synchronized void write(int value) { write(new byte[] {(byte) value}, 0, 1); }
  @Override public synchronized void write(byte[] value, int offset, int length) {
    if (length > bytes.length - size) { FaultCapture.fail(); return; }
    System.arraycopy(value, offset, bytes, size, length);
    size += length;
  }
  @Override public void close() { /* Remains owned through restoration scan and explicit wipe. */ }
  synchronized byte[] copy() { return Arrays.copyOf(bytes, size); }
  synchronized int size() { return size; }
  synchronized void wipe() { Arrays.fill(bytes, (byte) 0); size = 0; }
}

private static final class RawEvents extends ch.qos.logback.core.AppenderBase<ch.qos.logback.classic.spi.ILoggingEvent> {
  @Override protected void append(ch.qos.logback.classic.spi.ILoggingEvent event) { FaultCapture.raw(event); }
}

private static final class ConsoleRoute {
  final ch.qos.logback.core.ConsoleAppender<?> appender;
  final java.io.OutputStream stream;
  final ch.qos.logback.core.encoder.Encoder<?> encoder;
  final String target;
  final boolean started, flush;
  final List<?> filters;
  final QuarantineBytes quarantine = new QuarantineBytes();

  ConsoleRoute(ch.qos.logback.core.ConsoleAppender<?> original) {
    appender = original;
    stream = original.getOutputStream();
    encoder = original.getEncoder();
    target = original.getTarget();
    started = original.isStarted();
    flush = original.isImmediateFlush();
    filters = List.copyOf(original.getCopyOfAttachedFiltersList());
  }

  void validate(boolean installed) {
    if (appender.getClass() != ch.qos.logback.core.ConsoleAppender.class
        || appender.isWithJansi() || !started || !appender.isStarted()
        || !flush || appender.isImmediateFlush() != flush
        || encoder == null || encoder.getClass() != net.logstash.logback.encoder.LoggingEventCompositeJsonEncoder.class
        || !encoder.isStarted() || appender.getEncoder() != encoder
        || !target.equals(appender.getTarget()) || !filters.isEmpty()
        || !filters.equals(appender.getCopyOfAttachedFiltersList())
        || appender.getOutputStream() != (installed ? quarantine : stream)
        || encoder.headerBytes().length != 0 || encoder.footerBytes().length != 0) {
      FaultCapture.fail();
      throw closedFault(FaultCode.PREREQUISITE, 0, 0, FaultCapture.FAILURES.get());
    }
    var consoleTarget = "System.out".equals(target) ? ch.qos.logback.core.joran.spi.ConsoleTarget.SystemOut
        : "System.err".equals(target) ? ch.qos.logback.core.joran.spi.ConsoleTarget.SystemErr : null;
    if (consoleTarget == null || consoleTarget.getStream() != stream) {
      FaultCapture.fail();
      throw closedFault(FaultCode.PREREQUISITE, 0, 0, FaultCapture.FAILURES.get());
    }
  }
}

private record LoggerRoute(ch.qos.logback.classic.Logger logger, ch.qos.logback.classic.Level level,
    boolean additive, List<ch.qos.logback.core.Appender<ch.qos.logback.classic.spi.ILoggingEvent>> attached) {}

private static final class LogQuarantine {
  final ch.qos.logback.classic.LoggerContext context;
  final Map<ch.qos.logback.core.Appender<?>, ConsoleRoute> consoles = new java.util.IdentityHashMap<>();
  final Map<ch.qos.logback.classic.Logger, LoggerRoute> routes = new java.util.IdentityHashMap<>();
  final RawEvents raw = new RawEvents();
  final List<?> contextListeners;
  int statusCount, attachmentMultiplicity;
  boolean initialized;

  LogQuarantine() {
    Object factory = org.slf4j.LoggerFactory.getILoggerFactory();
    if (!(factory instanceof ch.qos.logback.classic.LoggerContext actual)) {
      throw closedFault(FaultCode.PREREQUISITE, 0, 0, 1);
    }
    context = actual;
    contextListeners = List.copyOf(context.getCopyOfListenerList());
  }

  void install() throws Exception {
    artifact(ch.qos.logback.core.ConsoleAppender.class,
        "e0f242aa3c4411ce8c7ec304a5afeaa75224680890f5f813153ef807cbb9542e");
    artifact(ch.qos.logback.classic.LoggerContext.class,
        "e223cce321ccb435d23e1dadfc6ceeccd862e2dabb1a2a5675318426f7fa1978");
    artifact(org.slf4j.LoggerFactory.class,
        "a12578dde1ba00bd9b816d388a0b879928d00bab3c83c240f7013bf4196c579a");
    artifact(net.logstash.logback.encoder.LoggingEventCompositeJsonEncoder.class,
        "81fcbde1b5a7d673d6c0d0d4f1e0f79b676f948e6b92b912e9e0b75097458bd3");
    if (!context.getTurboFilterList().isEmpty()
        || !context.getStatusManager().getCopyOfStatusListenerList().isEmpty()) {
      throw closedFault(FaultCode.PREREQUISITE, 0, 0, 1);
    }
    context.getLogger(org.slf4j.Logger.ROOT_LOGGER_NAME);
    context.getLogger("com.citi.put.checks");
    if (context.getLoggerList().size() > 512) {
      throw closedFault(FaultCode.PREREQUISITE, 0, 0, 1);
    }
    for (var logger : context.getLoggerList()) { register(logger, false); }
    if (consoles.isEmpty()) { throw closedFault(FaultCode.PREREQUISITE, 0, 0, 1); }
    for (ConsoleRoute route : consoles.values()) {
      route.validate(false);
      route.appender.setOutputStream(route.quarantine); // One public swap, original encoder stays active.
      route.validate(true);
    }
    raw.setContext(context);
    raw.setName("FAULT_CAPTURE_RAW");
    raw.start();
    for (LoggerRoute route : routes.values()) { route.logger.addAppender(raw); }
    context.getLogger(org.slf4j.Logger.ROOT_LOGGER_NAME).setLevel(ch.qos.logback.classic.Level.TRACE);
    context.getLogger("com.citi.put.checks").setLevel(ch.qos.logback.classic.Level.TRACE);
    statusCount = 0;
    inspectStatus();
    initialized = true;
  }

  private void artifact(Class<?> loaded, String expected) throws Exception {
    var location = loaded.getProtectionDomain().getCodeSource().getLocation().toURI();
    byte[] bytes = Files.readAllBytes(Path.of(location));
    byte[] digest = java.security.MessageDigest.getInstance("SHA-256").digest(bytes);
    try {
      if (!java.util.HexFormat.of().formatHex(digest).equals(expected)) {
        throw closedFault(FaultCode.PREREQUISITE, 0, 0, 1);
      }
    } finally { Arrays.fill(bytes, (byte) 0); Arrays.fill(digest, (byte) 0); }
  }

  private List<ch.qos.logback.core.Appender<ch.qos.logback.classic.spi.ILoggingEvent>> attached(
      ch.qos.logback.classic.Logger logger) {
    var originals = new java.util.ArrayList<ch.qos.logback.core.Appender<ch.qos.logback.classic.spi.ILoggingEvent>>();
    var iterator = logger.iteratorForAppenders();
    while (iterator.hasNext()) {
      var next = iterator.next();
      if (next != raw) { originals.add(next); }
    }
    return originals;
  }

  private void register(ch.qos.logback.classic.Logger logger, boolean newlyExisting) {
    if ((!logger.isAdditive() && !logger.getName().equals(org.slf4j.Logger.ROOT_LOGGER_NAME))
        || (newlyExisting && logger.getLevel() != null)) {
      throw closedFault(FaultCode.PREREQUISITE, 0, 0, 1);
    }
    var attached = attached(logger);
    if (newlyExisting && !attached.isEmpty()) {
      throw closedFault(FaultCode.PREREQUISITE, 0, 0, 1);
    }
    for (var appender : attached) {
      if (!(appender instanceof ch.qos.logback.core.ConsoleAppender<?> console)) {
        throw closedFault(FaultCode.PREREQUISITE, 0, 0, 1);
      }
      var route = consoles.computeIfAbsent(appender, unused -> new ConsoleRoute(console));
      route.validate(initialized);
      attachmentMultiplicity++;
    }
