      throw closedFault(FaultCode.PREREQUISITE, 0, 0, 1);
    }
    if (!context.isStarted() || !context.getTurboFilterList().isEmpty()
        || !context.getStatusManager().getCopyOfStatusListenerList().isEmpty()
        || !contextListeners.equals(context.getCopyOfListenerList())) {
      throw closedFault(FaultCode.PREREQUISITE, 0, 0, 1);
    }
    for (var logger : context.getLoggerList()) {
      if (!routes.containsKey(logger)) {
        if (afterRelease) {
          FaultCapture.fail(); // Late unknown route is not declared covered because it was quiet.
