  void probeRoutes() {
    for (LoggerRoute route : routes.values()) {
      if (route.logger.getName().equals(org.slf4j.Logger.ROOT_LOGGER_NAME)
          || route.logger.getName().startsWith("com.citi.put.checks")) {
        if (!route.logger.isTraceEnabled()) {
          FaultCapture.fail();
          continue;
        }
        int beforeRaw = FaultCapture.EVENTS.get();
        int beforeEncoded = consoles.values().stream().mapToInt(item -> item.quarantine.size()).sum();
        route.logger.trace("FAULT_CAPTURE_ROUTE_REGISTERED"); // Nonsensitive delivery support only.
        if (FaultCapture.EVENTS.get() <= beforeRaw
            || consoles.values().stream().mapToInt(item -> item.quarantine.size()).sum() <= beforeEncoded) {
