  void inspectStatus() {
    var statuses = context.getStatusManager().getCopyOfStatusList();
    if (statuses.size() < statusCount) { FaultCapture.fail(); }
    for (int index = Math.min(statusCount, statuses.size()); index < statuses.size(); index++) {
      var status = statuses.get(index);
      if (status.getEffectiveLevel() >= ch.qos.logback.core.status.Status.ERROR) { FaultCapture.fail(); }
      if (status.hasChildren()) { FaultCapture.fail(); } // Child status graphs are UNOBSERVED in this seam.
      FaultCapture.observe("LOGBACK_STATUS_MESSAGE", status.getMessage());
      FaultCapture.throwable(status.getThrowable());
